    silver_gardenseeddibberplate = { name = "Srebrn plošča za seme", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn plošča za seme za vrtnarje." },
