    jewel_set_gardenseeddibberplate = { name = "Draguljast plošča za seme", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast plošča za seme za vrtnarje." },
