    sovereign_gardenseeddibberplate_palace = { name = "Suverena gardenseeddibberplate palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GardenSeedDibberPlateMaker.ironStock=14; GardenSeedDibberPlateMaker.bronzeStock=12; GardenSeedDibberPlateMaker.woodStock=14; GardenSeedDibberPlateMaker.leatherStock=8; GardenSeedDibberPlateMaker.silverStock=8; GardenSeedDibberPlateMaker.goldStock=6; GardenSeedDibberPlateMaker.jewelStock=4; GardenSeedDibberPlateMaker.pearlStock=4
GardenSeedDibberPlateMaker.productStock = {}; GardenSeedDibberPlateMaker.buildings = {}; GardenSeedDibberPlateMaker.maker = nil; GardenSeedDibberPlateMaker.activeMaking = {}; GardenSeedDibberPlateMaker.totalProducts = 0; GardenSeedDibberPlateMaker.dayTimer = 0
function GardenSeedDibberPlateMaker.init() GardenSeedDibberPlateMaker.ironStock=14; GardenSeedDibberPlateMaker.bronzeStock=12; GardenSeedDibberPlateMaker.woodStock=14; GardenSeedDibberPlateMaker.leatherStock=8; GardenSeedDibberPlateMaker.silverStock=8; GardenSeedDibberPlateMaker.goldStock=6; GardenSeedDibberPlateMaker.jewelStock=4; GardenSeedDibberPlateMaker.pearlStock=4; GardenSeedDibberPlateMaker.productStock={}; GardenSeedDibberPlateMaker.buildings={}; GardenSeedDibberPlateMaker.maker=nil; GardenSeedDibberPlateMaker.activeMaking={}; GardenSeedDibberPlateMaker.totalProducts=0; GardenSeedDibberPlateMaker.dayTimer=0; print("[GardenSeedDibberPlateMaker] Royal Garden Seed Dibber Plate Maker System initialized (6 products, 4 buildings)") end
function GardenSeedDibberPlateMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenSeedDibberPlateMaker.maker={name=n or ("Ploščar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ploščar najet: %s (spretnost: %d)",GardenSeedDibberPlateMaker.maker.name,s),"success") end; return true end
function GardenSeedDibberPlateMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenSeedDibberPlateMaker.build(id) local ok,e=GardenSeedDibberPlateMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenSeedDibberPlateMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenSeedDibberPlateMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenSeedDibberPlateMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenSeedDibberPlateMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenSeedDibberPlateMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenSeedDibberPlateMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenSeedDibberPlateMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenSeedDibberPlateMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenSeedDibberPlateMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenSeedDibberPlateMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenSeedDibberPlateMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenSeedDibberPlateMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenSeedDibberPlateMaker.buildings==0 then return false,"Potrebna ploščna delavnica" end; if not GardenSeedDibberPlateMaker.maker then return false,"Potreben ploscar" end; return true end
function GardenSeedDibberPlateMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenSeedDibberPlateMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenSeedDibberPlateMaker.ironStock=GardenSeedDibberPlateMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenSeedDibberPlateMaker.bronzeStock=GardenSeedDibberPlateMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenSeedDibberPlateMaker.woodStock=GardenSeedDibberPlateMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenSeedDibberPlateMaker.leatherStock=GardenSeedDibberPlateMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenSeedDibberPlateMaker.silverStock=GardenSeedDibberPlateMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenSeedDibberPlateMaker.goldStock=GardenSeedDibberPlateMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenSeedDibberPlateMaker.jewelStock=GardenSeedDibberPlateMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenSeedDibberPlateMaker.pearlStock=GardenSeedDibberPlateMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenSeedDibberPlateMaker.maker then t=math.max(1,t-math.floor(GardenSeedDibberPlateMaker.maker.skill/13)) end; table.insert(GardenSeedDibberPlateMaker.activeMaking,{id="gardenseeddibberplate_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenSeedDibberPlateMaker.completeMaking(m) local q=1.0+(GardenSeedDibberPlateMaker.getQualityBonus()/100); if GardenSeedDibberPlateMaker.maker then q=q+(GardenSeedDibberPlateMaker.maker.skill/140) end; q=math.min(2.5,q); GardenSeedDibberPlateMaker.productStock[m.productType]=(GardenSeedDibberPlateMaker.productStock[m.productType] or 0)+m.quantity; GardenSeedDibberPlateMaker.totalProducts=GardenSeedDibberPlateMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenSeedDibberPlateMaker.maker then GardenSeedDibberPlateMaker.maker.itemsMade=GardenSeedDibberPlateMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenSeedDibberPlateMaker.maker.skill=math.min(100,GardenSeedDibberPlateMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Plošča izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardenseeddibberplate.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenSeedDibberPlateMaker.update(dt) if not _G.state then return end; GardenSeedDibberPlateMaker.dayTimer=GardenSeedDibberPlateMaker.dayTimer+dt; if GardenSeedDibberPlateMaker.dayTimer>=30 then GardenSeedDibberPlateMaker.dayTimer=0; for i=#GardenSeedDibberPlateMaker.activeMaking,1,-1 do local m=GardenSeedDibberPlateMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenSeedDibberPlateMaker.completeMaking(m); table.remove(GardenSeedDibberPlateMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenSeedDibberPlateMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenSeedDibberPlateMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenSeedDibberPlateMaker.getStats() return {ironStock=GardenSeedDibberPlateMaker.ironStock,bronzeStock=GardenSeedDibberPlateMaker.bronzeStock,woodStock=GardenSeedDibberPlateMaker.woodStock,leatherStock=GardenSeedDibberPlateMaker.leatherStock,silverStock=GardenSeedDibberPlateMaker.silverStock,goldStock=GardenSeedDibberPlateMaker.goldStock,jewelStock=GardenSeedDibberPlateMaker.jewelStock,pearlStock=GardenSeedDibberPlateMaker.pearlStock,productStock=GardenSeedDibberPlateMaker.productStock,numBuildings=#GardenSeedDibberPlateMaker.buildings,hasMaker=GardenSeedDibberPlateMaker.maker~=nil,makerName=GardenSeedDibberPlateMaker.maker and GardenSeedDibberPlateMaker.maker.name or "—",makerSkill=GardenSeedDibberPlateMaker.maker and GardenSeedDibberPlateMaker.maker.skill or 0,activeMaking=#GardenSeedDibberPlateMaker.activeMaking,totalProducts=GardenSeedDibberPlateMaker.totalProducts} end
